// Checks Claude's answer against the criteria of the position (read from the DB) and computes the score.
// Pure logic: nothing here trusts the numbers Claude copies back (names, weights come from the DB).
const REQUIRED_MIN = 5; // a required criterion below this → NOT_RECOMMENDED
const RECOMMENDED_MIN = 75;
const NOT_RECOMMENDED_BELOW = 50;

const round = (n, digits) => {
  const p = 10 ** digits;
  return Math.round((n + Number.EPSILON) * p) / p;
};
const text = (v) => (typeof v === 'string' ? v.trim() : '');
const list = (v) => (Array.isArray(v) ? v.map(text).filter(Boolean) : []);

function evaluate(dbCriteria, levelCodes, result) {
  if (!result || typeof result !== 'object' || !Array.isArray(result.criteria)) {
    throw new Error('the answer has no criteria list');
  }
  if (dbCriteria.length === 0) throw new Error('the position has no criteria');

  const given = new Map();
  for (const c of result.criteria) {
    const id = text(c && c.criterion_id);
    if (!id) throw new Error('a scored criterion has no criterion_id');
    if (given.has(id)) throw new Error('criterion ' + id + ' is scored more than once');
    given.set(id, c);
  }
  const known = new Set(dbCriteria.map((c) => c.id));
  const missing = dbCriteria.filter((c) => !given.has(c.id)).map((c) => c.name);
  if (missing.length) throw new Error('missing criteria: ' + missing.join(', '));
  const unknown = [...given.keys()].filter((id) => !known.has(id));
  if (unknown.length) throw new Error('unknown criterion ids: ' + unknown.join(', '));

  let weighted = 0;
  let weights = 0;
  let requiredFailed = false;
  const criteriaScores = dbCriteria.map((db) => {
    const c = given.get(db.id);
    const score = c.score;
    if (typeof score !== 'number' || !Number.isFinite(score) || score < 0 || score > 10) {
      throw new Error('the score of "' + db.name + '" must be a number from 0 to 10');
    }
    weighted += score * db.weight;
    weights += db.weight;
    if (db.is_required && score < REQUIRED_MIN) requiredFailed = true;
    return {
      criterion_id: db.id,
      name: db.name,
      type: db.type,
      weight: db.weight,
      is_required: db.is_required,
      score,
      reasoning: text(c.reasoning),
      evidence: text(c.evidence),
    };
  });
  if (!(weights > 0)) throw new Error('the weights of the criteria add up to 0');

  const overall = round((weighted / weights) * 10, 2);
  let recommendation = 'CONSIDER';
  if (requiredFailed || overall < NOT_RECOMMENDED_BELOW) recommendation = 'NOT_RECOMMENDED';
  else if (overall >= RECOMMENDED_MIN) recommendation = 'RECOMMENDED';

  const summary = text(result.summary);
  if (!summary) throw new Error('the answer has no summary');
  const years = result.estimated_years_experience;
  const level = text(result.estimated_level);
  return {
    overall_score: overall,
    recommendation,
    summary,
    strengths: list(result.strengths),
    weaknesses: list(result.weaknesses),
    criteria_scores: criteriaScores,
    estimated_years_experience: typeof years === 'number' && Number.isFinite(years) && years >= 0 ? round(years, 1) : null,
    estimated_level: levelCodes.includes(level) ? level : null,
  };
}

const config = $('Cấu hình').first().json;
const application = $('Nhận lô đơn').item.json;
const answer = $('Chấm điểm (AI Agent)').item.json.output;
const evaluation = evaluate($json.criteria, $json.levels, answer);

return {
  json: {
    application_id: application.id,
    overall_score: evaluation.overall_score,
    recommendation: evaluation.recommendation,
    summary: evaluation.summary,
    strengths: JSON.stringify(evaluation.strengths),
    weaknesses: JSON.stringify(evaluation.weaknesses),
    criteria_scores: JSON.stringify(evaluation.criteria_scores),
    estimated_years_experience: evaluation.estimated_years_experience,
    estimated_level: evaluation.estimated_level,
    model: config.model,
    prompt_version: config.prompt_version,
  },
};
